#!/usr/bin/env bash
# Creates a .env file with strong random secrets for local Docker use. Never overwrites an existing .env.
# Usage:  ./scripts/init-env.sh   then   docker compose --profile app up --build
set -euo pipefail
cd "$(dirname "$0")/.."

if [ -f .env ]; then
  echo ".env already exists - leaving it alone."
  exit 0
fi

secret() { openssl rand -base64 48 | tr -d '\n=+/' | cut -c1-48; }

cat > .env <<ENV
# Generated by scripts/init-env.sh. Never commit this file.
DB_USER=worksphere
DB_PASSWORD=$(secret)
JWT_SECRET=$(secret)
WEBHOOK_SECRET=$(secret)
STORAGE_ACCESS_KEY=worksphere
STORAGE_SECRET_KEY=$(secret)
METRICS_TOKEN=$(secret)
GRAFANA_PASSWORD=$(secret)
SEED_DEMO_DATA=true
PUBLIC_URL=http://localhost:8081
ENV
chmod 600 .env 2>/dev/null || true

# Prometheus reads the metrics token from a file (see infra/observability/prometheus.yml).
grep '^METRICS_TOKEN=' .env | cut -d= -f2- | tr -d '\n' > infra/observability/metrics-token

echo "Wrote .env and infra/observability/metrics-token with fresh random secrets."
